// Initialize i18n
i18n.use(initReactI18next).init({
  resources,
  lng: 'en', // default language
  fallbackLng: 'en',
  interpolation: {
    escapeValue: false, // react already safes from xss
  },
});

interface LanguageContextType {
  currentLanguage: Language;
  setLanguage: (language: Language) => void;
  ensureLanguageReady: () => Promise<void>;
  isLanguageReady: boolean;
  t: typeof i18n.t;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { preferences, updatePreferences } = usePreferences();
  const [isLanguageReady, setIsLanguageReady] = useState(false);
  const initRef = useRef<Promise<void> | null>(null);

  useEffect(() => {
    i18n.changeLanguage(preferences.language);
  }, [preferences.language]);

  const ensureLanguageReady = useCallback(async () => {
    if (isLanguageReady) {
      return;
    }

    if (initRef.current) {
      return initRef.current;
    }

    initRef.current = (async () => {
      try {
        await StorageInitializer.initialize();
        const stored = await AsyncStorage.getItem('userPreferences');
        if (stored) {
          try {
            const parsed = JSON.parse(stored);
            const storedLanguage = parsed?.language;
            if (storedLanguage && storedLanguage !== i18n.language) {
              await i18n.changeLanguage(storedLanguage);
            }
          } catch {
            // ignore parse errors
          }
          return;
        }

        const detected = detectDeviceLanguage();
        if (detected !== preferences.language) {
          updatePreferences({ language: detected });
        }
        await i18n.changeLanguage(detected);
      } catch {
        // ignore
      } finally {
        setIsLanguageReady(true);
      }
    })();

    return initRef.current;
  }, [isLanguageReady, preferences.language, updatePreferences]);

  useEffect(() => {
    ensureLanguageReady();
  }, [ensureLanguageReady]);
  
  const setLanguage = (language: Language) => {
    updatePreferences({ language });
    i18n.changeLanguage(language);
  };

  return (
    <LanguageContext.Provider value={{
      currentLanguage: preferences.language,
      setLanguage,
      ensureLanguageReady,
      isLanguageReady,
      t: i18n.t,
    }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

export default LanguageContext;
